/*
  ESP32-C3 SuperMini
  Puente transparente USB <-> UART
  UART física: 57600 bps
  RX = GPIO20
  TX = GPIO21
*/

#include <Arduino.h>

static constexpr uint32_t UART_BAUD = 57600;
static constexpr int UART_RX_PIN = 20;
static constexpr int UART_TX_PIN = 21;

void setup() {
  // Iniciar USB CDC
  Serial.begin(57600);

  // Esperar brevemente a que el USB esté disponible
  delay(500);

  // Mensaje de inicio
  Serial.println("aqui estoy");

  // Iniciar UART física
  Serial0.begin(
    UART_BAUD,
    SERIAL_8N1,
    UART_RX_PIN,
    UART_TX_PIN
  );
}

void loop() {
  // USB -> UART
  while (Serial.available() > 0) {
    int c = Serial.read();
    if (c >= 0) {
      Serial0.write((uint8_t)c);
    }
  }

  // UART -> USB
  while (Serial0.available() > 0) {
    int c = Serial0.read();
    if (c >= 0) {
      Serial.write((uint8_t)c);
    }
  }
}
